const weeklyGoalCompletionText = (row) => {
  const completion = text(row?.completion);
  if (completion) return completion;
  const status = text(row?.status);
  if (!status || status === "doing") return "";
  return WEEKLY_GOAL_STATUS_LABELS[status] || status;
};
const weeklyGoalCommentText = (row) => {
  const comment = text(row?.blockers);
  const legacyReflection = text(row?.reflection);
  if (!comment) return legacyReflection;
  if (!legacyReflection || legacyReflection === comment) return comment;
  return `${comment}\n\n${legacyReflection}`;
};
const weeklyGoalPreviousContext = (row) => {
  if (!row) return { plan: "", completion: "", handoff: [] };
  const plan = text(row.thisWeekGoal);
  const completion = weeklyGoalCompletionText(row);
  const handoff = (Array.isArray(row.nextThree) ? row.nextThree : []).map((item) => text(item)).filter(Boolean);
  return { plan, completion, handoff };
};
const weeklyGoalPreviousContextText = (row) => {
  if (!row) return "";
  const context = weeklyGoalPreviousContext(row);
  const parts = [];
  if (context.plan) parts.push(`上周计划：${context.plan}`);
  if (context.completion) parts.push(`完成&待办：${context.completion}`);
  if (context.handoff.length) parts.push(`上周交接：\n${context.handoff.map((item, index) => `${index + 1}. ${item}`).join("\n")}`);
  return parts.join("\n\n");
};
