const createLatestRequestQueue = () => {
  let generation = 0;
  let tail = Promise.resolve();
  return {
    enqueue(task) {
      const requestGeneration = ++generation;
      const isCurrent = () => requestGeneration === generation;
      const run = async () => await task(requestGeneration, isCurrent);
      const result = tail.then(run, run);
      tail = result.catch(() => undefined);
      return result;
    },
    isCurrent(requestGeneration) {
      return Number(requestGeneration) === generation;
    },
    invalidate() {
      generation += 1;
      return generation;
    },
  };
};
