    if (!visibleChildren.length) {
      if (liveLeafIdSet.has(nodeId)) assignLeafColor(nodeId, hueCenter, branchOrder, depth);
      return;
    }
    const weights = visibleChildren.map(([, childId]) => Math.max(1, collectVisibleLeafIds(childId).length));
    const totalWeight = weights.reduce((sum, weight) => sum + weight, 0);
    const gap = visibleChildren.length > 1 ? Math.min(4, hueSpan * 0.08) : 0;
    const usableSpan = Math.max(8, hueSpan - gap * Math.max(0, visibleChildren.length - 1));
    let cursor = hueCenter - usableSpan / 2;
