const getDailyLessonClipboardImagePayload = (clipboardData) => {
  const items = Array.from(clipboardData?.items || []);
  const imageItems = items.filter((item) => item?.kind === "file" && String(item.type || "").toLowerCase().startsWith("image/"));
  const itemFiles = imageItems.map((item) => {
    try { return item.getAsFile?.() || null; } catch (_) { return null; }
  }).filter(Boolean);
  if (itemFiles.length) {
    return {
      hasImagePayload: true,
      files: itemFiles.map((file, index) => normalizeDailyLessonClipboardImageFile(file, index)).filter(Boolean),
      failedItemCount: Math.max(0, imageItems.length - itemFiles.length),
      source: "items",
    };
  }
  const fallbackFiles = Array.from(clipboardData?.files || []).filter((file) => {
    const mime = String(file?.type || "").trim().toLowerCase();
    return mime.startsWith("image/") || !!getDailyLessonImageKindByExtension(getDailyLessonImageExtension(file?.name));
  });
  return {
    hasImagePayload: imageItems.length > 0 || fallbackFiles.length > 0,
    files: fallbackFiles.map((file, index) => normalizeDailyLessonClipboardImageFile(file, index)).filter(Boolean),
    failedItemCount: imageItems.length,
    source: fallbackFiles.length ? "files" : "none",
  };
};
