const getMandalaOntologyColumnPath = (ontology, tableIdValue, columnIdValue) => {
  const labels = [];
  const visited = new Set();
  let tableId = text(tableIdValue);
  let columnId = text(columnIdValue);
  while (tableId && columnId && !visited.has(tableId) && labels.length < 32) {
    visited.add(tableId);
    const table = ontology?.tablesById?.[tableId];
    const schema = ontology?.schemasById?.[text(table?.schemaId)];
    const column = schema?.columnsById?.[columnId];
    if (!isPlainObject(table) || !isPlainObject(schema) || !isPlainObject(column)) break;
    labels.unshift(text(column.label, columnId).slice(0, 120));
    if (tableId === text(ontology?.rootTableId)) break;
    const parentRef = table.parentCellRef;
    tableId = text(parentRef?.parentTableId);
    columnId = text(parentRef?.parentColumnId);
  }
  return labels.filter(Boolean);
};
