const mergeTypeConfigs = (rawTypes) => {
  const merged = {};
  Object.entries(DEFAULT_TYPES).forEach(([typeId, cfg], index) => {
    merged[typeId] = { ...cfg, parentId: "", order: index * 10 };
  });
  if (rawTypes && typeof rawTypes === "object" && !Array.isArray(rawTypes)) {
    Object.entries(rawTypes).forEach(([typeId, cfg], index) => {
      if (!typeId || !cfg || typeof cfg !== "object") return;
      const base = merged[typeId] || {};
      merged[typeId] = {
        ...base,
        ...cfg,
        name: text(cfg.name, base.name || typeId),
        color: normalizeHexColor(cfg.color, base.color || "#9ca3af"),
        icon: text(cfg.icon, base.icon || "🏷️") || "🏷️",
        parentId: text(cfg.parentId, base.parentId || ""),
        order: normalizeTypeOrder(cfg.order, base.order ?? ((Object.keys(DEFAULT_TYPES).length + index) * 10)),
      };
    });
  }
  return merged;
};

class PickerModal extends Modal {
  constructor(plugin, mandala, onPick) {
    super(plugin.app);
    this.plugin = plugin;
    this.mandala = mandala;
    this.onPick = onPick;
    this.keywordUiLease = plugin.getMandalaKeywordUiHost().lease();
    this.currentId = "root";
    this.history = [];
  }

  onOpen() {
    ensureRuntimeStyles();
    this.modalEl.addClass("mandala-time-blocks-picker-modal");
    this.render();
  }

  getKeywordIndex() {
    const entries = [];
    Object.values(this.mandala.nodeById || {}).forEach((node) => {
      if (!node?.id || node.id === "root") return;
      normalizeMandalaKeywords(node.keywords || []).forEach((keyword) => {
        entries.push({ keyword, nodeId: node.id, nodeTitle: node.title || node.id });
      });
    });
    const seen = new Map();
    entries.forEach((entry) => {
      const key = normalizeMandalaKeywordKey(entry.keyword);
      if (!key || seen.has(key)) return;
      seen.set(key, entry);
    });
    return Array.from(seen.values()).sort((a, b) => a.keyword.localeCompare(b.keyword, "zh-CN", { numeric: true, sensitivity: "base" }));
  }

  getContextCapsuleKeysSync() {
    return typeof this.plugin?.getContextCapsuleKeysSync === "function" ? this.plugin.getContextCapsuleKeysSync() : [];
  }

  getContextCapsuleKeyForKeyword(keywordLike = "") {
    return typeof this.plugin?.getContextCapsuleKeyForKeyword === "function" ? this.plugin.getContextCapsuleKeyForKeyword(keywordLike) : null;
  }

  getVirtualContextCapsuleKeys(keywordIndex = this.getKeywordIndex()) {
    return typeof this.plugin?.getVirtualContextCapsuleKeysForKeywords === "function" ? this.plugin.getVirtualContextCapsuleKeysForKeywords(keywordIndex) : [];
  }

  renderKeywordIndex(content) {
    return this.plugin.getMandalaKeywordUiHost().mount(content, this, this.keywordUiLease,
      stage => this.renderKeywordIndexSnapshot(stage));
  }

  renderKeywordIndexSnapshot(content) {
    const keywordIndex = this.getKeywordIndex().filter(entry => !this.plugin.isMandalaKeywordStopped(entry.keyword));
    const virtualContextKeys = this.getVirtualContextCapsuleKeys(keywordIndex).filter(key => !this.plugin.isMandalaKeywordStopped(key.displayLabel));
    if (!keywordIndex.length && !virtualContextKeys.length) return;
    const shell = make(content, "div", { cls: "mtb-grid-keyword-index" });
    make(shell, "div", { cls: "mtb-grid-keyword-title", text: "关键词定位" });
    const row = make(shell, "div", { cls: "mtb-keyword-index-row" });

    const combinedRows = [
      ...keywordIndex.map((entry) => ({ kind: "bound", entry, sortLabel: getContextCapsuleSortLabel(entry.keyword) })),
      ...virtualContextKeys.map((key) => ({ kind: "virtual", key, sortLabel: getContextCapsuleSortLabel(key.displayLabel) })),
    ].sort((left, right) => left.sortLabel.localeCompare(right.sortLabel, "zh-CN", { numeric: true, sensitivity: "base" }));
    combinedRows.forEach((rowItem) => {
      if (rowItem.kind === "virtual") {
        const key = rowItem.key;
        const button = make(row, "button", { cls: "mtb-node-keyword-chip mtb-context-capsule-virtual-chip", attr: { type: "button", title: `${key.displayLabel} · 虚位以待，尚未绑定九宫格节点` } });
        if (key.color) button.style.setProperty("--mtb-context-capsule-color", key.color);
        button.dataset.contextKeyId = key.contextKeyId;
        make(button, "span", { cls: "mtb-context-capsule-label", text: key.displayLabel });
        make(button, "span", { cls: "mtb-context-capsule-badge", text: "虚位" });
        button.onclick = () => new Notice(`操作上下文主键尚未绑定九宫格节点：${key.displayLabel}`);
        return;
      }
      const entry = rowItem.entry;
      const matchedContextKey = this.getContextCapsuleKeyForKeyword(entry.keyword);
      const button = make(row, "button", { cls: `mtb-node-keyword-chip${matchedContextKey ? " is-context-capsule-synced" : " is-context-capsule-local-only"}`, attr: { type: "button", title: this.mandala.getPath(entry.nodeId) } });
      if (matchedContextKey?.contextKeyId) button.dataset.contextKeyId = matchedContextKey.contextKeyId;
      if (matchedContextKey?.color) button.style.setProperty("--mtb-context-capsule-color", matchedContextKey.color);
      make(button, "span", { cls: "mtb-context-capsule-label", text: entry.keyword });
      if (matchedContextKey) make(button, "span", { cls: "mtb-context-capsule-badge", text: "同步" });
      else make(button, "span", { cls: "mtb-context-capsule-badge", text: "本地" });
      button.onclick = () => {
        if (!this.mandala.nodeById[entry.nodeId]) return;
        this.history.push(this.currentId);
        this.currentId = entry.nodeId;
        this.render();
      };
    });
  }

  async render() {
    const content = this.contentEl;
    this.plugin.getMandalaKeywordUiHost().releaseOwner(this);
    clear(content);
    const current = this.mandala.nodeById[this.currentId] || this.mandala.nodeById.root;
    make(content, "h3", { text: "选择九宫格节点" });
    make(content, "div", { cls: "mtb-picker-path", text: this.mandala.getPath(current.id) });
    const actions = make(content, "div", { cls: "mtb-picker-actions" });
    const back = make(actions, "button", { text: "⬅ 上一级" });
    back.disabled = this.history.length === 0;
    back.onclick = () => {
      if (!this.history.length) return;
      this.currentId = this.history.pop();
      this.render();
    };
    make(actions, "button", { text: "回到根" }).onclick = () => {
      this.currentId = "root";
      this.history = [];
      this.render();
    };
    const tips = make(content, "div", { cls: "mtb-muted", text: "中间是当前节点；四周是它的九宫格槽位。非末端节点可继续展开，也可用下方按钮选择当前节点。" });
    tips.style.marginBottom = "10px";
    this.renderKeywordIndex(content);
    const grid = make(content, "div", { cls: "mtb-manage-grid" });
    forceNineGridStyle(grid);
    const coreLeaf = this.mandala.leafById.has(current.id);
    for (let index = 0; index < 9; index += 1) {
      const cell = make(grid, "button", { cls: "mtb-manage-cell" });
      forceNineCellStyle(cell);
      const isCore = index === 4;
      const nodeId = isCore ? current.id : current.children?.[index];
      const node = nodeId ? this.mandala.nodeById[nodeId] : null;
      if (!node) {
        cell.classList.add("is-empty");
        cell.disabled = true;
        cell.textContent = "·";
        continue;
      }
      if (isCore) cell.classList.add("is-core");
      const isLeaf = this.mandala.leafById.has(node.id);
      if (isLeaf) cell.classList.add("is-leaf");
      const imageUrl = await this.plugin.getNodeImage(node, this.plugin.getPaths().sourceNotePath);
      if (imageUrl) {
        const bg = make(cell, "div", { cls: "mtb-manage-cell-bg" });
        bg.style.backgroundImage = `url("${imageUrl}")`;
      }
      cell.style.borderColor = isCore ? "var(--interactive-accent)" : "var(--background-modifier-border)";
      if (isLeaf) {
        decorateLeafTerminalCell(cell, "", isCore);
        make(cell, "div", { cls: "mtb-manage-cell-terminal", text: "✦ 终点" });
      }
      const title = make(cell, "div", { cls: "mtb-manage-cell-title", text: node.title || "未命名" });
      title.title = this.mandala.getPath(node.id);
      const sub = make(cell, "div", { cls: "mtb-manage-cell-subtitle", text: isLeaf ? "节点，可选" : "继续展开，可选" });
      if (!isLeaf) {
        const pickCurrent = make(cell, "div", { cls: "mtb-manage-cell-terminal", text: "选择" });
        pickCurrent.onclick = (event) => {
          event.stopPropagation();
          this.close();
          this.onPick(node);
        };
      }
      cell.onclick = () => {
        if (isLeaf) {
          this.close();
          this.onPick(node);
          return;
        }
        this.history.push(this.currentId);
        this.currentId = node.id;
        this.render();
      };
    }
    const selectWrap = make(content, "div", { cls: "mtb-section-actions" });
    make(selectWrap, "button", { cls: "mod-cta", text: `选择当前节点：${current.title}` }).onclick = () => {
      this.close();
      this.onPick(current);
    };
  }

  onClose() {
    this.plugin.mandalaKeywordUiHost?.releaseOwner(this);
    clear(this.contentEl);
  }
}

class ConfirmActionModal extends Modal {
  constructor(app, options = {}) {
    super(app);
    this.titleText = options.title || "确认操作";
    this.message = options.message || "";
    this.detail = options.detail || "";
    this.confirmText = options.confirmText || "确认";
    this.cancelText = options.cancelText || "取消";
    this.confirmClass = options.confirmClass || "mod-warning";
    this.onConfirm = options.onConfirm || (() => {});
    this.onCancel = options.onCancel || (() => {});
    this.done = false;
    this.allowClose = false;
    this.cancelNotified = false;
  }

  onOpen() {
    ensureRuntimeStyles();
    this.modalEl.addClass("mandala-time-blocks-confirm-modal");
    this.modalEl.style.width = "520px";
    this.modalEl.style.maxWidth = "92vw";
    const content = this.contentEl;
    clear(content);
    make(content, "h3", { text: this.titleText });
    make(content, "p", { cls: "mtb-confirm-message", text: this.message });
    if (this.detail) make(content, "div", { cls: "mtb-confirm-detail", text: this.detail });
    const actions = make(content, "div", { cls: "mtb-modal-actions" });
    const cancelButton = make(actions, "button", { text: this.cancelText });
    cancelButton.onclick = () => this.close();
    const confirmButton = make(actions, "button", { cls: this.confirmClass, text: this.confirmText });
    confirmButton.onclick = async () => {
      if (this.done) return;
      this.done = true;
      cancelButton.disabled = true;
      confirmButton.disabled = true;
      try {
        await this.onConfirm();
        this.allowClose = true;
        this.close();
      } catch (error) {
        this.done = false;
        cancelButton.disabled = false;
        confirmButton.disabled = false;
        console.error("[MandalaTimeBlocks][confirm-action.failed]", { title: this.titleText, message: error?.message || String(error) });
        new Notice(error?.message || "操作未完成，请重试");
        confirmButton.focus();
      }
    };
  }

  close() {
    if (this.done && !this.allowClose) return false;
    return super.close();
  }

  onClose() {
    if (!this.allowClose && !this.cancelNotified) {
      this.cancelNotified = true;
      try { this.onCancel(); } catch (_) {}
    }
    clear(this.contentEl);
  }
}

class DailyLessonImagePreviewModal extends Modal {
  constructor(plugin, record, launcher = null) {
    super(plugin.app);
    this.plugin = plugin;
    this.record = record;
    this.launcher = launcher;
  }

  onOpen() {
    ensureRuntimeStyles();
    this.modalEl.addClass("mandala-time-blocks-daily-image-preview-modal");
    const content = this.contentEl;
    clear(content);
    make(content, "h3", { text: "查看日课图片" });
    const resolved = this.plugin.resolveDailyLessonImagePreview(this.record?.target);
    if (resolved?.url) {
      const stage = make(content, "div", { cls: "mtb-daily-image-preview-stage" });
      const image = make(stage, "img", { cls: "mtb-daily-image-preview-full", attr: { alt: this.record?.target || "日课图片" } });
      image.src = resolved.url;
    } else {
      make(content, "div", { cls: "mtb-daily-image-unresolved", text: `当前引用无法解析：${this.record?.target || "未知图片"}` });
    }
    make(content, "div", { cls: "mtb-daily-image-path", text: this.record?.target || "" });
    const actions = make(content, "div", { cls: "mtb-modal-actions" });
    const closeButton = make(actions, "button", { cls: "mod-cta", text: "关闭" });
    closeButton.onclick = () => this.close();
    window.setTimeout(() => closeButton.focus(), 0);
  }

  onClose() {
    clear(this.contentEl);
    if (this.launcher?.isConnected) this.launcher.focus();
  }
}

class DailyLessonImageAlbumModal extends Modal {
  constructor(plugin, date, launcher = null) {
    super(plugin.app);
    this.plugin = plugin;
    this.date = normalizeDailyLessonDateKey(date);
    this.launcher = launcher;
    this.renderGeneration = 0;
    this.closed = false;
  }

  onOpen() {
    ensureRuntimeStyles();
    this.modalEl.addClass("mandala-time-blocks-daily-image-album-modal");
    this.closed = false;
    void this.render();
  }

  async render() {
    const generation = ++this.renderGeneration;
    const content = this.contentEl;
    clear(content);
    const loading = make(content, "div", { cls: "mtb-muted", text: "正在读取相册..." });
    const day = await this.plugin.getDailyLessonDay(this.date);
    if (this.closed || generation !== this.renderGeneration) return;
    loading.remove();
    const projection = getDailyLessonCommentProjection(day.adjustment || day.summary || "");
    const head = make(content, "div", { cls: "mtb-daily-image-album-head" });
    const titleWrap = make(head, "div", { cls: "mtb-daily-image-album-title" });
    make(titleWrap, "h3", { text: "日课图片相册" });
    make(titleWrap, "div", { cls: "mtb-muted", text: `${this.date} · ${projection.imageCount} 张` });
    const imageInput = make(head, "input", {
      cls: "mtb-daily-image-file-input",
      attr: { type: "file", accept: ".png,.jpg,.jpeg,.webp,.gif,.bmp,image/png,image/jpeg,image/webp,image/gif,image/bmp", multiple: "multiple", tabindex: "-1" },
    });
    const addButton = make(head, "button", { cls: "mtb-daily-image-add mod-cta", attr: { type: "button", "aria-label": `向 ${this.date} 的日课相册添加图片` } });
    setIcon(addButton, "image-plus");
    make(addButton, "span", { text: "添加图片" });
    addButton.disabled = !this.plugin.canAcceptDailyLessonImageImports();
    addButton.onclick = () => imageInput.click();
    imageInput.onchange = async () => {
      const files = Array.from(imageInput.files || []);
      imageInput.value = "";
      if (!files.length) return;
      addButton.disabled = true;
      try {
        await this.plugin.enqueueDailyLessonImageImport(this.date, files);
        await this.render();
      } finally {
        if (addButton.isConnected) addButton.disabled = !this.plugin.canAcceptDailyLessonImageImports();
      }
    };
    const grid = make(content, "div", { cls: "mtb-daily-image-album-grid", attr: { role: "list", "aria-label": `${this.date} 日课图片` } });
    if (!projection.records.length) {
      make(grid, "div", { cls: "mtb-daily-image-album-empty", text: "当前还没有图片。" });
    }
    projection.records.forEach((record, index) => {
      const tile = make(grid, "div", { cls: "mtb-daily-image-album-tile", attr: { role: "listitem" } });
      const resolved = this.plugin.resolveDailyLessonImagePreview(record.target);
      const previewButton = make(tile, "button", {
        cls: "mtb-daily-image-thumbnail-button",
        attr: { type: "button", "aria-label": `查看第 ${index + 1} 张图片：${record.target}` },
      });
      if (resolved?.url) {
        const image = make(previewButton, "img", { cls: "mtb-daily-image-thumbnail", attr: { alt: record.target } });
        image.src = resolved.url;
      } else {
        setIcon(previewButton, "image-off");
        make(previewButton, "span", { text: "引用无法解析" });
      }
      previewButton.onclick = () => new DailyLessonImagePreviewModal(this.plugin, record, previewButton).open();
      make(tile, "div", { cls: "mtb-daily-image-caption", text: record.target, attr: { title: record.target } });
      const removeButton = make(tile, "button", {
        cls: "mtb-daily-image-remove",
        attr: {
          type: "button",
          title: "移除图片引用（附件文件保留）",
          "aria-label": `移除第 ${index + 1} 张图片引用，附件文件将保留`,
        },
      });
      setIcon(removeButton, "unlink");
      removeButton.onclick = () => {
        const frozen = Object.assign({}, record, {
          date: this.date,
          fieldHash: hashDailyLessonComment(day.adjustment || day.summary || ""),
          updatedAt: day.updatedAt || "",
        });
        new ConfirmActionModal(this.plugin.app, {
          title: "移除这张图片引用？",
          message: "确认后只会从当天的“记录、想法、路点与线索”中移除这一条引用。Obsidian 附件文件会保留。",
          detail: record.target,
          confirmText: "移除引用",
          onConfirm: async () => {
            const result = await this.plugin.removeDailyLessonImageReference(frozen);
            if (!result?.ok) throw new Error(result?.message || "图片引用已变化，请刷新相册后重试。");
            await this.plugin.refreshDailyLessonImageProjectionForDate(this.date, result.value);
            await this.render();
          },
        }).open();
      };
    });
    const drop = make(content, "div", { cls: "mtb-daily-image-drop-zone", attr: { tabindex: "0" }, text: "可将一张或多张图片拖到这里" });
    const setDrag = (active) => drop.classList.toggle("is-dragover", active);
    drop.ondragenter = (event) => { event.preventDefault(); setDrag(true); };
    drop.ondragover = (event) => { event.preventDefault(); if (event.dataTransfer) event.dataTransfer.dropEffect = "copy"; setDrag(true); };
    drop.ondragleave = (event) => { if (!event.relatedTarget || !drop.contains(event.relatedTarget)) setDrag(false); };
    drop.ondrop = async (event) => {
      event.preventDefault();
      event.stopPropagation();
      setDrag(false);
      const files = Array.from(event.dataTransfer?.files || []);
      const vaultFiles = files.length ? [] : this.plugin.resolveDroppedDailyLessonVaultImages(event.dataTransfer);
      if (!files.length && !vaultFiles.length) return;
      if (files.length) await this.plugin.enqueueDailyLessonImageImport(this.date, files);
      else await this.plugin.enqueueDailyLessonVaultImageImport(this.date, vaultFiles);
      await this.render();
    };
    const actions = make(content, "div", { cls: "mtb-modal-actions" });
    const closeButton = make(actions, "button", { text: "关闭" });
    closeButton.onclick = () => this.close();
    window.setTimeout(() => (addButton.disabled ? closeButton : addButton).focus(), 0);
  }

  onClose() {
    this.closed = true;
    this.renderGeneration += 1;
    clear(this.contentEl);
    if (this.launcher?.isConnected) this.launcher.focus();
  }
}

class StructuredFieldImageAlbumModal extends Modal {
  constructor(plugin, descriptor, launcher = null) {
    super(plugin.app);
    this.plugin = plugin;
    this.descriptor = normalizeStructuredFieldDescriptor(descriptor);
    this.launcher = launcher;
    this.renderGeneration = 0;
    this.closed = false;
  }

  onOpen() {
    ensureRuntimeStyles();
    this.modalEl.addClass("mandala-time-blocks-daily-image-album-modal");
    this.closed = false;
    void this.render();
  }

  async render() {
    const generation = ++this.renderGeneration;
    const content = this.contentEl;
    clear(content);
    const loading = make(content, "div", { cls: "mtb-muted", text: "正在读取相册..." });
    const snapshot = await this.plugin.getStructuredFieldSnapshot(this.descriptor);
    if (this.closed || generation !== this.renderGeneration) return;
    loading.remove();
    if (!snapshot?.ok) {
      make(content, "div", { cls: "mtb-error", text: snapshot?.message || "当前字段来源已不存在，未创建新的数据 owner。" });
      return;
    }
    const projection = getDailyLessonCommentProjection(snapshot.value);
    const head = make(content, "div", { cls: "mtb-daily-image-album-head" });
    const titleWrap = make(head, "div", { cls: "mtb-daily-image-album-title" });
    make(titleWrap, "h3", { text: "字段图片相册" });
    make(titleWrap, "div", { cls: "mtb-muted", text: `${this.descriptor.label || "结构化字段"} · ${projection.imageCount} 张` });
    const imageInput = make(head, "input", {
      cls: "mtb-daily-image-file-input",
      attr: { type: "file", accept: ".png,.jpg,.jpeg,.webp,.gif,.bmp,image/png,image/jpeg,image/webp,image/gif,image/bmp", multiple: "multiple", tabindex: "-1" },
    });
    const addButton = make(head, "button", { cls: "mtb-daily-image-add mod-cta", attr: { type: "button", "aria-label": "向当前字段添加图片" } });
    setIcon(addButton, "image-plus");
    make(addButton, "span", { text: "添加图片" });
    addButton.disabled = !this.plugin.canAcceptStructuredFieldImageImports();
    addButton.onclick = () => imageInput.click();
    imageInput.onchange = async () => {
      const files = Array.from(imageInput.files || []);
      imageInput.value = "";
      if (!files.length) return;
      addButton.disabled = true;
      try {
        await this.plugin.enqueueStructuredFieldImageImport(this.descriptor, files);
        await this.render();
      } finally {
        if (addButton.isConnected) addButton.disabled = !this.plugin.canAcceptStructuredFieldImageImports();
      }
    };
    const grid = make(content, "div", { cls: "mtb-daily-image-album-grid", attr: { role: "list", "aria-label": "字段图片" } });
    if (!projection.records.length) make(grid, "div", { cls: "mtb-daily-image-album-empty", text: "当前还没有图片。" });
    projection.records.forEach((record, index) => {
      const tile = make(grid, "div", { cls: "mtb-daily-image-album-tile", attr: { role: "listitem" } });
      const resolved = this.plugin.resolveDailyLessonImagePreview(record.target, this.descriptor.sourceNotePath);
      const previewButton = make(tile, "button", { cls: "mtb-daily-image-thumbnail-button", attr: { type: "button", "aria-label": `查看第 ${index + 1} 张图片` } });
      if (resolved?.url) {
        const image = make(previewButton, "img", { cls: "mtb-daily-image-thumbnail", attr: { alt: record.target } });
        image.src = resolved.url;
      } else {
        setIcon(previewButton, "image-off");
        make(previewButton, "span", { text: "引用无法解析" });
      }
      previewButton.onclick = () => new DailyLessonImagePreviewModal(this.plugin, record, previewButton).open();
      make(tile, "div", { cls: "mtb-daily-image-caption", text: record.target, attr: { title: record.target } });
      const removeButton = make(tile, "button", {
        cls: "mtb-daily-image-remove",
        attr: { type: "button", title: "移除图片引用（附件文件保留）", "aria-label": `移除第 ${index + 1} 张图片引用` },
      });
      setIcon(removeButton, "unlink");
      removeButton.onclick = () => {
        const isReferencedDailyItem = this.descriptor.domain === "daily-item" && this.plugin.isStructuredFieldDailyItemReferenced(this.descriptor);
        const frozen = Object.assign({}, record, {
          descriptor: this.descriptor,
          fieldHash: hashDailyLessonComment(snapshot.value),
          updatedAt: snapshot.updatedAt || "",
        });
        new ConfirmActionModal(this.plugin.app, {
          title: "移除这张图片引用？",
          message: isReferencedDailyItem
            ? "确认后会修改本位日课事项的“此前的经验”，所有引用该事项的状态都会同步变化。只移除引用，Obsidian 附件文件仍保留。"
            : "确认后只移除当前字段中的这一条引用，Obsidian 附件文件仍保留。",
          detail: record.target,
          confirmText: "移除引用",
          onConfirm: async () => {
            const result = await this.plugin.removeStructuredFieldImageReference(frozen);
            if (!result?.ok) throw new Error(result?.message || "图片引用已变化，请刷新相册后重试。");
            await this.render();
          },
        }).open();
      };
    });
    const drop = make(content, "div", { cls: "mtb-daily-image-drop-zone", attr: { tabindex: "0" }, text: "可将一张或多张图片拖到这里" });
    const setDrag = (active) => drop.classList.toggle("is-dragover", active);
    drop.ondragenter = (event) => { event.preventDefault(); setDrag(true); };
    drop.ondragover = (event) => { event.preventDefault(); if (event.dataTransfer) event.dataTransfer.dropEffect = "copy"; setDrag(true); };
    drop.ondragleave = (event) => { if (!event.relatedTarget || !drop.contains(event.relatedTarget)) setDrag(false); };
    drop.ondrop = async (event) => {
      event.preventDefault();
      event.stopPropagation();
      setDrag(false);
      const files = Array.from(event.dataTransfer?.files || []);
      const vaultFiles = files.length ? [] : this.plugin.resolveDroppedDailyLessonVaultImages(event.dataTransfer);
      if (!files.length && !vaultFiles.length) return;
      if (files.length) await this.plugin.enqueueStructuredFieldImageImport(this.descriptor, files);
      else await this.plugin.enqueueStructuredFieldVaultImageImport(this.descriptor, vaultFiles);
      await this.render();
    };
    const actions = make(content, "div", { cls: "mtb-modal-actions" });
    const closeButton = make(actions, "button", { text: "关闭" });
    closeButton.onclick = () => this.close();
    window.setTimeout(() => (addButton.disabled ? closeButton : addButton).focus(), 0);
  }

  onClose() {
    this.closed = true;
    this.renderGeneration += 1;
    clear(this.contentEl);
    if (this.launcher?.isConnected) this.launcher.focus();
  }
}

class TypeConfigModal extends Modal {
  constructor(app, options = {}) {
    super(app);
    this.options = options;
    this.result = null;
    this.waiter = new Promise((resolve) => {
      this._resolve = resolve;
    });
  }

  onOpen() {
    const { contentEl } = this;
    clear(contentEl);
    this.modalEl.addClass("mandala-time-blocks-type-config-modal");
    make(contentEl, "h3", { text: this.options.title || "类型" });
    if (this.options.description) make(contentEl, "p", { cls: "mtb-muted", text: this.options.description });
    const form = make(contentEl, "div", { cls: "mtb-type-config-form" });
    make(form, "label", { text: "名称" });
    const name = make(form, "input", { attr: { placeholder: "类型名称" } });
    name.value = this.options.name || "";
    make(form, "label", { text: "emoji" });
    const icon = make(form, "input", { attr: { placeholder: "🏷️" } });
    icon.value = this.options.icon || "🏷️";
    make(form, "label", { text: "颜色" });
    const color = make(form, "input", { attr: { type: "color" } });
    color.value = normalizeHexColor(this.options.color, "#3b82f6");
    const actions = make(contentEl, "div", { cls: "mtb-modal-actions" });
    make(actions, "button", { text: "取消" }).onclick = () => this.close();
    make(actions, "button", { cls: "mod-cta", text: "保存" }).onclick = () => {
      const finalName = text(name.value);
      if (!finalName) return new Notice("类型名称不能为空");
      this.result = {
        name: finalName,
        icon: text(icon.value, "🏷️"),
        color: normalizeHexColor(color.value, "#3b82f6"),
      };
      this.close();
    };
    window.setTimeout(() => name.focus(), 0);
  }

  onClose() {
    clear(this.contentEl);
    if (typeof this._resolve === "function") this._resolve(this.result);
  }

  waitForResult() {
    this.open();
    return this.waiter;
  }
}

class NoteBindingModal extends Modal {
  constructor(app, options = {}) {
    super(app);
    this.options = options;
    this.result = null;
    this.filtered = [];
    this.activeIndex = 0;
    this.waiter = new Promise((resolve) => {
      this._resolve = resolve;
    });
  }

  onOpen() {
    const { contentEl } = this;
    const noteIndex = Array.isArray(this.options.noteIndex) ? this.options.noteIndex : [];
    const currentValue = text(this.options.value);
    clear(contentEl);
    this.modalEl.addClass("mandala-time-blocks-note-binding-modal");
    this.modalEl.style.width = "min(980px, calc(100vw - 32px))";
    this.modalEl.style.maxWidth = "calc(100vw - 32px)";
    this.modalEl.style.height = "min(80vh, 760px)";
    make(contentEl, "h3", { text: this.options.title || "绑定 Obsidian 笔记" });
    make(contentEl, "p", { cls: "mtb-muted", text: "从当前 vault 的 Markdown 笔记列表中选择，也可以输入库内相对路径。" });
    if (currentValue) {
      const current = make(contentEl, "div", { cls: "mtb-note-current" });
      make(current, "div", { cls: "mtb-note-current-label", text: "当前绑定" });
      make(current, "div", { cls: "mtb-note-current-path", text: currentValue });
      const currentActions = make(current, "div", { cls: "mtb-inline-row mtb-wrap" });
      make(currentActions, "button", { text: "打开当前绑定" }).onclick = () => {
        if (typeof this.options.onOpenCurrent === "function") this.options.onOpenCurrent();
      };
      make(currentActions, "button", { text: "清除绑定" }).onclick = () => {
        this.result = { action: "clear", value: "" };
        this.close();
      };
    }
    const input = make(contentEl, "input", { cls: "mtb-note-search-input", attr: { type: "text", placeholder: "输入关键词筛选，或直接输入路径后绑定" } });
    input.value = currentValue;
    const stat = make(contentEl, "div", { cls: "mtb-muted" });
    const list = make(contentEl, "div", { cls: "mtb-note-picker-list" });
    const syncRows = () => {
      Array.from(list.children).forEach((child, index) => {
        if (child?.classList) child.classList.toggle("is-active", index === this.activeIndex);
      });
    };
    const renderList = () => {
      const terms = qText(input.value).split(/\s+/).filter(Boolean);
      const matched = !terms.length
        ? noteIndex.slice(0, 240)
        : noteIndex.filter((item) => {
          const hay = `${item.search || ""} ${item.basenameLower || ""} ${item.pathLower || ""}`;
          return terms.every((term) => hay.includes(term));
        }).slice(0, 240);
      this.filtered = matched;
      if (this.activeIndex >= matched.length) this.activeIndex = Math.max(0, matched.length - 1);
      stat.textContent = `共 ${matched.length} 条结果`;
      clear(list);
      if (!matched.length) {
        make(list, "div", { cls: "mtb-muted", text: "无匹配笔记" });
        return;
      }
      matched.forEach((item, index) => {
        const row = make(list, "div", { cls: `mtb-note-picker-row ${index === this.activeIndex ? "is-active" : ""}`.trim() });
        make(row, "div", { cls: "mtb-note-picker-title", text: `📝 ${item.basename}` });
        make(row, "div", { cls: "mtb-note-picker-path", text: item.path });
        row.onclick = () => {
          this.result = { action: "save", value: item.path };
          this.close();
        };
        row.onmouseenter = () => {
          this.activeIndex = index;
          syncRows();
        };
      });
    };
    input.addEventListener("input", () => {
      this.activeIndex = 0;
      renderList();
    });
    input.addEventListener("keydown", (event) => {
      if (event.key === "ArrowDown") {
        event.preventDefault();
        if (this.activeIndex < this.filtered.length - 1) this.activeIndex += 1;
        syncRows();
      } else if (event.key === "ArrowUp") {
        event.preventDefault();
        if (this.activeIndex > 0) this.activeIndex -= 1;
        syncRows();
      } else if (event.key === "Enter") {
        event.preventDefault();
        const selected = this.filtered[this.activeIndex];
        this.result = { action: "save", value: selected?.path || text(input.value) };
        this.close();
      }
    });
    const actions = make(contentEl, "div", { cls: "mtb-modal-actions" });
    make(actions, "button", { text: "清除绑定" }).onclick = () => {
      this.result = { action: "clear", value: "" };
      this.close();
    };
    make(actions, "button", { text: "取消" }).onclick = () => this.close();
    make(actions, "button", { cls: "mod-cta", text: "绑定输入内容" }).onclick = () => {
      this.result = { action: "save", value: text(input.value) };
      this.close();
    };
    renderList();
    window.setTimeout(() => {
      input.focus();
      input.select();
    }, 0);
  }

  onClose() {
    this.modalEl.style.width = "";
    this.modalEl.style.maxWidth = "";
    this.modalEl.style.height = "";
    clear(this.contentEl);
    if (typeof this._resolve === "function") this._resolve(this.result);
  }

  waitForResult() {
    this.open();
    return this.waiter;
  }
}

