    make(actionCell, "button", { text: "打开" }).onclick = async () => {
      await this.flushAllDrafts(false);
      this.workspaceNodeId = row.nodeId;
      this.displayTitle = nodeTitle;
      this.workspaceDisplayTitle = nodeTitle;
      this.contextLabel = "项目管理 / Workspace 主键";
      this.setActiveTab("workspaceNode");
      await this.render();
    };
    const markDirty = () => {
      this.workspaceSummaryDirty = true;
    };
    [goalInput, completionInput, commentInput, ...nextInputs].forEach((input) => {
      input.addEventListener("input", markDirty);
      input.addEventListener("change", markDirty);
    });
    this.workspaceSummaryRows.push({
      nodeId: row.nodeId,
      weekId: row.weekId,
      displayTitle: nodeTitle,
      titleProvenance: row.historicalSourceMissing ? text(row.titleProvenance, "legacy_row_evidence") : "observed_in_week",
      goalInput,
      completionInput,
      commentInput,
      nextInputs,
    });
