      if (draft.sourceNotePath !== this.sourceNotePath) continue;
      if (Array.from(this.plugin.dailyViews || []).some(view => view !== this && !view.closed && view.draftKey() === key)) continue;
      const box = make(this.statusEl, "details"); make(box, "summary", { text: `保留草稿 · ${draft.payload?.date} · ${draft.updatedAt}` });
      make(box, "textarea", { attr: { rows: "5", readonly: "readonly" } }).value = JSON.stringify(draft.payload, null, 2);
