class MTBSettingTab extends PluginSettingTab {
  constructor(app, plugin) {
    super(app, plugin);
    this.plugin = plugin;
  }

  display() {
    const { containerEl } = this;
    containerEl.empty();
    containerEl.createEl("h2", { text: "Mandala Time Blocks 设置" });
    new Setting(containerEl)
      .setName("默认源笔记")
      .setDesc("用于定位 Mandala_Database.json、Mandala_Types.json 与新插件 JSON 的主源笔记路径。")
      .addText((textBox) =>
        textBox
          .setPlaceholder(DEFAULT_NOTE)
          .setValue(this.plugin.settings.defaultSourceNotePath || DEFAULT_NOTE)
          .onChange(value => { this.c2SourceDraft = norm(value || DEFAULT_NOTE); })
      ).addButton(button=>button.setButtonText('核对并切换来源').onClick(()=>{
        const oldSource=this.plugin.settings.defaultSourceNotePath||DEFAULT_NOTE,newSource=this.c2SourceDraft||oldSource;
        if(newSource===oldSource)return;
        const modal=new Modal(this.app);let sourceModalLive=true;modal.onClose=()=>{sourceModalLive=false;};modal.onOpen=()=>{
          modal.contentEl.createEl('h3',{text:'切换九宫格来源'});modal.contentEl.createEl('p',{text:oldSource+' → '+newSource});
          modal.contentEl.createEl('p',{text:'已登记目标仍属于原来源。切换不会迁移身份、内容或绑定；若原来源已有中心管理目标，本次切换会被阻止。'});
          let sourceSaved=false;const confirm=modal.contentEl.createEl('button',{text:'确认核验并切换'});confirm.onclick=async()=>{if(sourceSaved||!sourceModalLive||confirm.disabled||this.app.plugins?.plugins?.['mandala-time-blocks']!==this.plugin)return;confirm.disabled=true;try{
            if((this.plugin.settings.defaultSourceNotePath||DEFAULT_NOTE)!==oldSource)throw Error('来源已变化，请重新打开设置');
            const api=this.app.plugins?.plugins?.['context-key-manager']?.getNamingProjectionAuthorityV1?.();if(!api)throw Error('管理中心未就绪');
            const availability=api.availability();if(availability.state==='unavailable')throw Error('管理中心需要恢复');
            if(availability.state==='configured'){
              const snapshot=api.snapshot();const state=snapshot;
              if(!state||!Array.isArray(state.contexts))throw Error('无法核验已登记目标');
              if(state.contexts.some(c=>c.naming?.authority==='center'&&c.subjects.some(r=>r.domain==='goal'&&r.sourceScope===oldSource)))throw Error('原来源存在中心管理目标，请先完成来源与绑定迁移后再切换');
              api.assertCurrent(snapshot);
            }
            api.assertAvailability(availability);
            this.plugin.settings.defaultSourceNotePath=newSource;this.plugin.syncTrackingRevisionSource();
            try{await this.plugin.saveSettings();}catch(error){this.plugin.settings.defaultSourceNotePath=oldSource;this.plugin.syncTrackingRevisionSource();throw error;}
            sourceSaved=true;await this.plugin.ensureSourceSettings();await this.plugin.syncRelationAdapter();modal.close();new Notice('来源已切换，请重新打开相关视图并重新预览管理操作');
          }catch(error){modal.contentEl.createEl('p',{text:(sourceSaved?'来源已保存，但初始化或刷新尚未完成。请关闭并重新打开设置与相关视图，不要重复切换：':'未完成：')+error.message});}finally{confirm.disabled=sourceSaved;}};
        };modal.open();
      })
      );
  }
}

async function verifyPersistedRelationMembershipV1(request, options) {
  const {adapter, sourcePath, viewType, notePath, adapterId, assertCurrent, keysFromData, hash} = options;
  assertCurrent();
  if (!request || request.version !== 1 || request.adapterId !== adapterId ||
      request.viewType !== viewType || request.notePath !== notePath || !request.requestToken ||
      !Array.isArray(request.nodeKeys) || !sourcePath) throw Error("INDEX_MEMBERSHIP_REQUEST");
  const wanted = [...request.nodeKeys].sort();
  if (wanted.some(x => typeof x !== "string" || !x || x.trim() !== x) || new Set(wanted).size !== wanted.length) throw Error("INDEX_MEMBERSHIP_KEYS");
  if (!await adapter.exists(sourcePath)) throw Error("INDEX_MEMBERSHIP_SOURCE_MISSING");
  assertCurrent();
  const raw = await adapter.read(sourcePath);
  assertCurrent();
  if (typeof raw !== "string") throw Error("INDEX_MEMBERSHIP_RAW");
  const keys = keysFromData(JSON.parse(raw)).sort();
  if (new Set(keys).size !== keys.length || JSON.stringify(keys) !== JSON.stringify(wanted)) throw Error("INDEX_MEMBERSHIP_MISMATCH");
  const after = await adapter.read(sourcePath);
  assertCurrent();
  if (after !== raw) throw Error("INDEX_MEMBERSHIP_CHANGED");
  return {version:1, kind:"persisted-owner-membership", adapterId, viewType, notePath, sourcePath,
    requestToken:request.requestToken, nodeKeys:keys, revision:hash(raw)};
}


