  async setDailyLessonMode(dateValue = "", modeValue = DAILY_LESSON_SIDE_NORMAL) {
    const mode = normalizeDailyLessonSide(modeValue, DAILY_LESSON_SIDE_NORMAL);
    return await this.enqueueDailyLessonMutation(`set-mode:${normalizeDailyLessonDateKey(dateValue || todayKey())}:${mode}`, async () => await this.setDailyLessonModeUnlocked(dateValue, mode));
  }

  async setDailyLessonModeUnlocked(dateValue = "", modeValue = DAILY_LESSON_SIDE_NORMAL) {
    const date = normalizeDailyLessonDateKey(dateValue || todayKey());
    const store = await this.loadDailyLessons(true);
    const now = nowIso();
    const mode = normalizeDailyLessonSide(modeValue, DAILY_LESSON_SIDE_NORMAL);
    const nextFlipped = mode !== DAILY_LESSON_SIDE_NORMAL;
    const seeded = mode === DAILY_LESSON_SIDE_STRESS
      ? this.ensureDefaultStressDailyLessonItemsInStore(store)
      : mode === DAILY_LESSON_SIDE_KAIOKEN
        ? this.ensureDefaultKaiokenDailyLessonItemsInStore(store)
        : mode === DAILY_LESSON_SIDE_ADJUST
          ? this.ensureDefaultAdjustDailyLessonItemsInStore(store)
          : mode === DAILY_LESSON_SIDE_HEALTH
            ? this.ensureDefaultHealthDailyLessonItemsInStore(store)
            : mode === DAILY_LESSON_SIDE_RECUPERATION
              ? this.ensureDefaultRecuperationDailyLessonItemsInStore(store)
              : mode === DAILY_LESSON_SIDE_NEW_HOME
                ? this.ensureDefaultNewHomeDailyLessonItemsInStore(store)
                : mode === DAILY_LESSON_SIDE_FREE_ENERGY
                  ? this.ensureDefaultFreeEnergyDailyLessonItemsInStore(store)
                  : mode === DAILY_LESSON_SIDE_SOCIAL_CONDUCT
                    ? this.ensureDefaultSocialConductDailyLessonItemsInStore(store)
                    : mode === DAILY_LESSON_SIDE_SELF_RESTRAINT
                      ? this.ensureDefaultSelfRestraintDailyLessonItemsInStore(store)
                      : mode === DAILY_LESSON_SIDE_CHECKLIST
                        ? this.ensureDefaultChecklistDailyLessonItemsInStore(store)
                        : 0;
    const current = normalizeDailyStressDay(store.stressDaysByDate?.[date], { date });
    store.stressDaysByDate = Object.assign({}, store.stressDaysByDate || {}, {
      [date]: normalizeDailyStressDay(Object.assign({}, current, {
        date,
        mode,
        flipped: nextFlipped,
        flippedAt: nextFlipped ? (current.flippedAt || now) : current.flippedAt,
        restoredAt: nextFlipped ? "" : now,
        updatedAt: now,
      }), { date }),
    });
    await this.saveDailyLessonsUnlocked(store);
    console.info("[MandalaTimeBlocks][daily-lessons.save]", { action: "set-daily-lesson-mode", date, mode, seeded, path: this.getPaths().dailyLessons });
    return clone(store.stressDaysByDate[date], null);
  }

  async setDailyLessonFlipState(dateValue = "", flipped = true) {
    return await this.setDailyLessonMode(dateValue, flipped === true ? DAILY_LESSON_SIDE_STRESS : DAILY_LESSON_SIDE_NORMAL);
  }

  getDailyLessonItemsForDateFromStore(store, dateValue = "", options = {}) {
    const date = normalizeDailyLessonDateKey(dateValue || todayKey());
    const flipState = this.getDailyLessonFlipStateFromStore(store, date);
    const mode = normalizeDailyLessonSide(flipState.mode, flipState.flipped ? DAILY_LESSON_SIDE_STRESS : DAILY_LESSON_SIDE_NORMAL);
    return this.getDailyLessonProjectedItemsForSideFromStore(store, mode, options);
  }

  getDailyLessonOverviewItemsForDateRangeFromStore(store, startValue = "", endValue = "") {
    const start = normalizeDailyLessonDateKey(startValue || todayKey());
    const end = normalizeDailyLessonDateKey(endValue || start);
    const itemById = new Map();
    const allItemsById = new Map();
    DAILY_LESSON_SIDE_ORDER.forEach((side) => {
      this.getDailyLessonItems(store, { includeInactive: true, side }).forEach((item) => {
        setDailyLessonItemByIdCollisionSafe(allItemsById, item.id, item);
      });
    });
    dateKeysBetween(start, end, 14).forEach((date) => {
      const day = normalizeDailyLessonDay(store.daysByDate?.[date], { date });
      this.getDailyLessonItemsForDateFromStore(store, date, { includeInactive: true }).forEach((item) => {
        if (item.active === false && !day.entriesByItemId?.[item.id]) return;
        itemById.set(text(item.id), item);
      });
      Object.entries(day.entriesByItemId || {}).forEach(([rawId, entry]) => {
        const id = text(rawId);
        const item = allItemsById.get(id);
        if (!item) return;
        if (entry?.done !== true && !text(entry?.note).trim()) return;
        itemById.set(id, item);
      });
    });
    return Array.from(itemById.values()).sort((a, b) => {
      const sideDiff = DAILY_LESSON_SIDE_ORDER.indexOf(a.side) - DAILY_LESSON_SIDE_ORDER.indexOf(b.side);
      if (sideDiff) return sideDiff;
      return text(a.name, a.id).localeCompare(text(b.name, b.id), "zh-CN", { numeric: true, sensitivity: "base" });
    });
  }

  async getDailyLessonOverviewItemsForDateRange(startValue = "", endValue = "") {
    const store = await this.loadDailyLessons(false);
    return this.getDailyLessonOverviewItemsForDateRangeFromStore(store, startValue, endValue);
  }

  getDailyLessonDayFromStore(store, dateValue = "") {
    const date = normalizeDailyLessonDateKey(dateValue);
    const day = normalizeDailyLessonDay(store.daysByDate?.[date], { date });
    const flipState = this.getDailyLessonFlipStateFromStore(store, date);
    const mode = normalizeDailyLessonSide(flipState.mode, flipState.flipped ? DAILY_LESSON_SIDE_STRESS : DAILY_LESSON_SIDE_NORMAL);
    return {
      date,
      side: mode,
      mode,
      stressFlipped: flipState.flipped === true,
      flipState,
      items: this.getDailyLessonItemsForDateFromStore(store, date, { includeInactive: true }).map((item) => clone(item, item)),
      plan: day.plan,
      completion: day.completion,
      adjustment: day.adjustment,
      tomorrowPlan: day.tomorrowPlan,
      summary: day.summary,
      entriesByItemId: clone(day.entriesByItemId || {}, {}),
      updatedAt: day.updatedAt,
    };
  }

