  listDailyLessonDaysFromStore(store, options = {}) {
    const start = normalizeDailyLessonDateKey(options.start || options.startDate || todayKey());
    const end = normalizeDailyLessonDateKey(options.end || options.endDate || start);
    const dates = dateKeysBetween(start, end, Number(options.maxDays) || 120);
    return dates.map((date) => {
      const day = normalizeDailyLessonDay(store.daysByDate?.[date], { date });
      return {
        date,
        plan: day.plan,
        completion: day.completion,
        adjustment: day.adjustment,
        tomorrowPlan: day.tomorrowPlan,
        summary: day.summary,
        entriesByItemId: clone(day.entriesByItemId || {}, {}),
        updatedAt: day.updatedAt,
      };
    });
  }

