  getDailyLessonCompletionStatsFromStore(store, itemIds = [], weekStart = "", weekEnd = "") {
    const ids = Array.from(new Set((Array.isArray(itemIds) ? itemIds : []).map((id) => text(id)).filter(Boolean)));
    const result = {};
    ids.forEach((id) => {
      result[id] = { weekDone: 0, weekTotal: 0, totalDone: 0, totalDays: 0, firstDoneDate: "" };
    });
    if (!ids.length) return result;
    const weekDates = dateKeysBetween(weekStart, weekEnd, 14);
    const today = todayKey();
    weekDates.forEach((date) => {
      const day = normalizeDailyLessonDay(store.daysByDate?.[date], { date });
      const seenForDate = new Set();
      this.getDailyLessonItemsForDateFromStore(store, date, { includeInactive: true }).forEach((item) => {
        const id = text(item?.id);
        if (!result[id] || seenForDate.has(id)) return;
        if (item.active === false && !day.entriesByItemId?.[id]) return;
        seenForDate.add(id);
        result[id].weekTotal += 1;
      });
    });
    Object.entries(store.daysByDate || {})
      .sort(([a], [b]) => text(a).localeCompare(text(b)))
      .forEach(([date, day]) => {
        ids.forEach((id) => {
          const done = day?.entriesByItemId?.[id]?.done === true;
          if (!done) return;
          if (weekDates.includes(date)) result[id].weekDone += 1;
          if (!result[id].firstDoneDate) result[id].firstDoneDate = date;
          if (date <= today) result[id].totalDone += 1;
        });
      });
    ids.forEach((id) => {
      const firstDone = result[id].firstDoneDate;
      result[id].totalDays = firstDone ? dateSpanDaysInclusive(firstDone, today) : 0;
    });
    return result;
  }

